//! The "Mewrk concise" built-in texts: what the host says to a frontier model.
//!
//! The guided texts in [`super::english`] steer models that need it; these keep
//! only what a strong model cannot infer and that changes what it does —
//! host-specific lifecycle, result shapes it must reference, limits the schema
//! cannot express — and say nothing where a tool's name and schema already do.
//!
//! One arm per key, exhaustive and in registry order like [`super::english`]:
//! `same` keeps the guided text, `""` omits it, a literal replaces it, and
//! `(as Key)` — for a tool variant (see `crate::tool_surface`) whose concise
//! wording has nothing its variants differ on — reads what `Key` resolves to. A key added
//! to the registry therefore needs a decision here before it compiles.

use super::PromptKey;

macro_rules! concise_texts {
    ($( $variant:ident => $value:tt ),* $(,)?) => {
        /// The concise text for `key`, or `None` where it keeps the guided one.
        pub(super) fn text(key: PromptKey) -> Option<&'static str> {
            match key {
                $( PromptKey::$variant => concise_texts!(@value $value), )*
            }
        }

        /// The variants in the order this table lists them, for the order test.
        #[cfg(test)]
        pub(super) const ORDER: &[PromptKey] = &[ $( PromptKey::$variant, )* ];
    };
    (@value same) => { None };
    // Another variant of the same tool whose concise text says nothing the
    // two variants differ on: this key reads exactly what that key resolves
    // to. The guided texts of the two differ, so `same` would not do.
    (@value (as $other:ident)) => { Some(PromptKey::$other.builtin_concise()) };
    (@value $text:literal) => { Some($text) };
}

